var st={cls:'',tier:'normal',KIT:{},theme:'dark'};

/* ── LANG SYSTEM ── */
function fillSel(id,arr){
  var s=el(id);if(!s)return;
  var i=s.selectedIndex<0?0:s.selectedIndex;
  s.innerHTML='';
  arr.forEach(function(o){var op=document.createElement('option');op.textContent=(L==='th'?o.th:o.en);s.appendChild(op);});
  s.selectedIndex=i;
}
function applyText(){
  qa('[data-en]').forEach(function(e){
    var v=(L==='th'?(e.getAttribute('data-th')||e.getAttribute('data-en')):e.getAttribute('data-en'));
    if(v!=null)e.textContent=v;
  });
}
function applyPlace(){
  qa('[data-pen]').forEach(function(e){
    var v=(L==='th'?(e.getAttribute('data-pth')||e.getAttribute('data-pen')):e.getAttribute('data-pen'));
    if(v!=null)e.setAttribute('placeholder',v);
  });
}
function setLang(l){
  L=l;
  el('lg_en').classList.toggle('on',l==='en');
  el('lg_th').classList.toggle('on',l==='th');
  applyText();applyPlace();
  for(var k in SELS)fillSel(k+'_sel',SELS[k]);
  redrawKit();
}
el('lg_en').addEventListener('click',function(){setLang('en');});
el('lg_th').addEventListener('click',function(){setLang('th');});

/* ── THEME ── */
el('tog_dark').addEventListener('click',function(){
  el('app').classList.remove('lt');
  el('tog_dark').classList.add('on');el('tog_light').classList.remove('on');
  st.theme='dark';
});
el('tog_light').addEventListener('click',function(){
  el('app').classList.add('lt');
  el('tog_light').classList.add('on');el('tog_dark').classList.remove('on');
  st.theme='light';
});

/* ── TABS ── */
function goTab(t){
  qa('.tab').forEach(function(b){b.classList.toggle('on',b.getAttribute('data-tab')===t);});
  qa('.panel').forEach(function(p){p.classList.toggle('on',p.getAttribute('data-panel')===t);});
}
qa('.tab').forEach(function(b){b.addEventListener('click',function(){goTab(b.getAttribute('data-tab'));});});
qa('.nb[data-next]').forEach(function(b){b.addEventListener('click',function(){goTab(b.getAttribute('data-next'));});});

/* ── MANA COLOR PICKER ── */
var SW=['#c8a84b','#4488ff','#ff4444','#44cc88','#aa44ff','#ffffff','#ff8800','#00ccff'];
(function(){
  var box=el('f_sws');
  SW.forEach(function(hx){
    var s=document.createElement('span');s.className='sw';s.style.background=hx;s.setAttribute('data-c',hx);
    s.addEventListener('click',function(){setMana(hx);});
    box.appendChild(s);
  });
})();
function isHex(v){v=v.replace('#','');if(v.length!==6)return false;for(var i=0;i<6;i++){if('0123456789abcdef'.indexOf(v.charAt(i).toLowerCase())<0)return false;}return true;}
function setMana(hx){
  el('f_manacolor').value=hx;
  el('f_manahex').value=hx.toUpperCase();
  qa('.sw').forEach(function(s){s.classList.toggle('on',s.getAttribute('data-c').toLowerCase()===hx.toLowerCase());});
}
el('f_manacolor').addEventListener('input',function(){setMana(this.value);});
el('f_manahex').addEventListener('input',function(){var v=this.value.trim();if(isHex(v)){if(v.charAt(0)!=='#')v='#'+v;el('f_manacolor').value=v;}});
setMana('#c8a84b');

/* ── PRESET/CUSTOM TOGGLES ── */
qa('.pc').forEach(function(p){
  qa('.pcb',p).forEach(function(b){
    b.addEventListener('click',function(){
      qa('.pcb',p).forEach(function(x){x.classList.remove('on');});b.classList.add('on');
      var n=p.getAttribute('data-t'),m=b.getAttribute('data-m');
      el(n+'_sel').classList.toggle('hide',m!=='p');
      el(n+'_cus').classList.toggle('hide',m!=='c');
    });
  });
});
function getPC(n){
  var p=document.querySelector('.pc[data-t="'+n+'"]');
  var m=p.querySelector('.pcb.on').getAttribute('data-m');
  return m==='p'?el(n+'_sel').value:(el(n+'_cus').value||'').trim();
}

